package com.fasterxml.jackson.databind.cfg;

import com.fasterxml.jackson.annotation.JsonAutoDetect;
import com.fasterxml.jackson.annotation.PropertyAccessor;
import com.fasterxml.jackson.core.Base64Variant;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.impl.StdAnnotationIntrospector;
import com.fasterxml.jackson.databind.cfg.impl.StdClassIntrospector;
import com.fasterxml.jackson.databind.cfg.impl.StdVisibilityChecker;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospectorPair;
import com.fasterxml.jackson.databind.introspect.ClassIntrospector;
import com.fasterxml.jackson.databind.introspect.VisibilityChecker;
import com.fasterxml.jackson.databind.jsontype.TypeResolverBuilder;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.type.TypeResolverBuilder;
import com.fasterxml.jackson.databind.util.StdDateFormat;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class BaseSettings_with_TriageGen1Test {

    private ClassIntrospector _classIntrospector;
    private AnnotationIntrospector _annotationIntrospector;
    private VisibilityChecker<?> _visibilityChecker;
    private PropertyNamingStrategy _propertyNamingStrategy;
    private TypeFactory _typeFactory;
    private TypeResolverBuilder<?> _typeResolverBuilder;
    private HandlerInstantiator _handlerInstantiator;
    private Locale _locale;
    private Base64Variant _defaultBase64;

    @Before
    public void setUp() {
        _classIntrospector = new StdClassIntrospector(String.class);
        _annotationIntrospector = new StdAnnotationIntrospector();
        _visibilityChecker = new StdVisibilityChecker();
        _propertyNamingStrategy = PropertyNamingStrategy.LOWER_CAMEL_CASE;
        _typeFactory = TypeFactory.defaultInstance();
        _typeResolverBuilder = mock(TypeResolverBuilder.class);
        _handlerInstantiator = mock(HandlerInstantiator.class);
        _locale = Locale.US;
        _defaultBase64 = Base64Variant.MIME;
    }

    @Test(expected = IllegalArgumentException.class)
    public void testWith_NullTimeZone_ThrowsException() {
        BaseSettings settings = createBaseSettings(new SimpleDateFormat());
        settings.with(null);
    }

    @Test
    public void testWith_StdDateFormat_UsesWithTimeZone() {
        StdDateFormat stdDateFormat = new StdDateFormat();
        BaseSettings settings = createBaseSettings(stdDateFormat);
        TimeZone newTz = TimeZone.getTimeZone("UTC");

        BaseSettings newSettings = settings.with(newTz);

        assertNotNull(newSettings);
        assertEquals(newTz, newSettings.getTimeZone());
        assertTrue(newSettings.getDateFormat() instanceof StdDateFormat);
        assertEquals(newTz, newSettings.getDateFormat().getTimeZone());
        // Ensure it's a different instance if StdDateFormat.withTimeZone returns a new one
        assertNotSame(settings, newSettings);
    }

    @Test
    public void testWith_NonStdDateFormat_UsesClone() {
        // SimpleDateFormat is not an instance of StdDateFormat
        SimpleDateFormat simpleDateFormat = new SimpleDateFormat("yyyy-MM-dd");
        BaseSettings settings = createBaseSettings(simpleDateFormat);
        TimeZone newTz = TimeZone.getTimeZone("GMT");

        BaseSettings newSettings = settings.with(newTz);

        assertNotNull(newSettings);
        assertEquals(newTz, newSettings.getTimeZone());
        assertEquals(newTz, newSettings.getDateFormat().getTimeZone());

        // Verify that clone was called (the original should remain unchanged)
        assertNotSame(settings.getDateFormat(), newSettings.getDateFormat());
        assertNotEquals(simpleDateFormat.getTimeZone(), newSettings.getDateFormat().getTimeZone());
        assertEquals(simpleDateFormat.getTimeZone(), settings.getDateFormat().getTimeZone());
    }

    @Test
    public void testWith_PreservesOtherFields() {
        DateFormat df = new StdDateFormat();
        BaseSettings settings = createBaseSettings(df);
        TimeZone newTz = TimeZone.getTimeZone("Asia/Tokyo");

        BaseSettings newSettings = settings.with(newTz);

        assertEquals(_classIntrospector, newSettings.getClassIntrospector());
        assertEquals(_annotationIntrospector, newSettings.getAnnotationIntrospector());
        assertEquals(_visibilityChecker, newSettings.getVisibilityChecker());
        assertEquals(_propertyNamingStrategy, newSettings.getPropertyNamingStrategy());
        assertEquals(_typeFactory, newSettings.getTypeFactory());
        assertEquals(_typeResolverBuilder, newSettings.getTypeResolverBuilder());
        assertEquals(_handlerInstantiator, newSettings.getHandlerInstantiator());
        assertEquals(_locale, newSettings.getLocale());
        assertEquals(_defaultBase64, newSettings.getBase64Variant());
    }

    private BaseSettings createBaseSettings(DateFormat df) {
        return new BaseSettings(
                _classIntrospector,
                _annotationIntrospector,
                _visibilityChecker,
                _propertyNamingStrategy,
                _typeFactory,
                _typeResolverBuilder,
                df,
                _handlerInstantiator,
                _locale,
                TimeZone.getDefault(),
                _defaultBase64
        );
    }
}
